"""Independent rational-identity, proof and domain checks; requires SymPy."""
import argparse,json
from pathlib import Path
import sympy as s
p=argparse.ArgumentParser();p.add_argument('--output',required=True,type=Path);args=p.parse_args();x,y=s.symbols('x y');R=s.Rational;checks=[]
def ck(label,a,b):
 ok=s.simplify(a-b)==0
 checks.append({'check':label,'passed':bool(ok)})
 if not ok:raise AssertionError((label,a,b))
