('1.3.1a',(8*x-1)/((x+1)*(x-2)),3/(x+1)+5/(x-2)),('1.3.1b',(2*x+13)/((2*x-1)*(x+3)),4/(2*x-1)-1/(x+3)),('1.3.1c',(7-11*x)/((3*x-1)*(2*x+1)),2/(3*x-1)-5/(2*x+1)),
('1.3.2a',(7*x-15)/(x*x-5*x),3/x+4/(x-5)),('1.3.2b',3*(x+7)/(x*x-9),5/(x-3)-2/(x+3)),('1.3.2c',(9*x-1)/(2*x*x-9*x-5),1/(2*x+1)+4/(x-5)),
('1.3.3a',(6*x*x-43*x+50)/(x*(x-2)*(x-5)),5/x+2/(x-2)-1/(x-5)),('1.3.3b',(4*x*x+11*x+9)/((x-1)*(x+2)*(x+3)),2/(x-1)-1/(x+2)+3/(x+3)),('1.3.3c',(5*x*x-22*x+6)/(x*(x-3)*(2*x-1)),2/x-1/(x-3)+3/(2*x-1)),
('1.3.4',(1+15*x-10*x*x)/((x-2)*(1-2*x)),5+3/(x-2)-4/(1-2*x)),('1.3.5',4/((x+1)*(3*x-2)),-R(4,5)/(x+1)+R(12,5)/(3*x-2)),('1.3.6',(5*x-3)/((2*x+3)*(x+2)),13/(x+2)-21/(2*x+3)),('1.3.7',3/(9-y*y),1/(2*(3-y))+1/(2*(3+y))),('1.3.8',(33*x-x*x-44)/((x-1)*(x+5)*(2*x-3)),2/(x-1)-3/(x+5)+1/(2*x-3)),('1.3.9',(2*x*x-11)/((x+1)*(x-2)),2+3/(x+1)-1/(x-2)),
