('1.5.1',(x*x-5*x+7)/(x-3),x-2+1/(x-3)),('1.5.2',(x*x-5*x+9)/(x+1),x-6+15/(x+1)),('1.5.3',(x**3-x*x-9)/(x+3),x*x-4*x+12-45/(x+3)),('1.5.4',x**3-2*x*x+5,(x*x+2*x+8)*(x-4)+37),('1.5.5',(18*x*x+22*x-7)/((x+2)*(3*x-1)),6-3/(x+2)+1/(3*x-1)),('1.5.6',(2*x**3-4*x*x+5*x-1)/(x-3),2*x*x+2*x+11+32/(x-3)),('1.5.7',(x**4-3*x*x+5)/(x*x+2),x*x-5+15/(x*x+2)),('1.5.8',(4*x*x-5*x-3)/((x+1)*(2*x-1)),2-2/(x+1)-3/(2*x-1)),('1.5.9',3*x**4-5*x**3+6*x*x-12*x+5,(3*x*x-5*x)*(x*x+2)-2*x+5),
